const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the geometry for the Madre de Dios region in Peru.
    const geometry = ee.Geometry.Rectangle([-72.4, -13.2, -68.7, -10.0]);

    // Define the years for comparison.
    const year1 = 2013;
    const year2 = 2018;

    // 2. Data Acquisition
    const collection = ee.ImageCollection('MODIS/006/MCD12Q1');

    // Get the land cover image for 2013.
    const image1_col = collection.filterDate(`${year1}-01-01`, `${year1}-12-31`).select('LC_Type1');
    // Get the land cover image for 2018.
    const image2_col = collection.filterDate(`${year2}-01-01`, `${year2}-12-31`).select('LC_Type1');

    // 3. Data Availability Check
    const size1 = image1_col.size().getInfo();
    const size2 = image2_col.size().getInfo();

    if (size1 === 0 || size2 === 0) {
        console.log(`Image count for ${year1}: ${size1}`);
        console.log(`Image count for ${year2}: ${size2}`);
        console.log("No images found for one or both years.");
        console.log("A: No");
        return;
    }

    const image1 = image1_col.first();
    const image2 = image2_col.first();

    // 4. Processing: Create Forest Masks
    // IGBP classification considers classes 1-5 as forest.
    const forestMask1 = image1.gte(1).and(image1.lte(5));
    const forestMask2 = image2.gte(1).and(image2.lte(5));

    // Calculate pixel area image.
    const pixelArea = ee.Image.pixelArea();

    // Calculate forest area by multiplying the mask by the pixel area.
    const forestArea1 = forestMask1.multiply(pixelArea);
    const forestArea2 = forestMask2.multiply(pixelArea);

    // 5. Calculation
    const scale = 1000; // Use a coarse scale to avoid timeouts for a large region.

    // Calculate total forest area for 2013.
    const area1_result = forestArea1.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    // Calculate total forest area for 2018.
    const area2_result = forestArea2.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    // Check pixel counts to prevent C2 error.
    const count1 = forestMask1.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).get('LC_Type1').getInfo();

    if (count1 === 0) {
        console.log("No valid pixels found in the region for the initial period.");
        console.log("C2: No Valid Pixels");
        return;
    }

    // 6. Validation & Final Answer
    const area1_m2 = area1_result.get('LC_Type1').getInfo();
    const area2_m2 = area2_result.get('LC_Type1').getInfo();

    if (area1_m2 === null || area2_m2 === null) {
        console.log("Calculation failed. Result is null.");
        console.log("C3: Calculation Failure");
        return;
    }

    // Convert area from square meters to square kilometers for readability.
    const area1_km2 = area1_m2 / 1e6;
    const area2_km2 = area2_m2 / 1e6;

    console.log(`Forest Cover ${year1} (km^2): ${area1_km2.toLocaleString('en-US', {maximumFractionDigits: 0})}`);
    console.log(`Forest Cover ${year2} (km^2): ${area2_km2.toLocaleString('en-US', {maximumFractionDigits: 0})}`);

    const change = area2_km2 - area1_km2;
    console.log(`Change (km^2): ${change.toLocaleString('en-US', {maximumFractionDigits: 0})}`);

    if (area2_km2 < area1_km2) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('Authentication or Initialization failed:', e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
